/**
 * Normalize a duration in seconds to a finite, non-negative integer.
 *
 * Negative values, NaN and the infinities are treated as zero so callers can
 * never render "-1h -1m", "NaNm" or "Infinity:Infinity" from bad clock math.
 */
function toNonNegativeSeconds(seconds: number): number {
  if (!Number.isFinite(seconds) || seconds <= 0) return 0;
  return Math.floor(seconds);
}

export function formatDuration(seconds: number): string {
  const total = toNonNegativeSeconds(seconds);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  if (h > 0) return `${h}h ${m}m`;
  return `${m}m`;
}

export function formatTag(username: string, discriminator: string): string {
  return `${username}#${discriminator}`;
}

export function formatTime(seconds: number): string {
  const s = toNonNegativeSeconds(seconds);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

